sksl:
uniform shader image;
uniform float2 size;
uniform float phase;
uniform float amount;
uniform float lineCount;
half4 effectMain(float2 coord){half4 c=image.eval(coord);float v=0.5+0.5*cos((coord.y/size.y*lineCount+phase)*6.2831853);return half4(c.rgb*half(1.0-amount*(1.0-v)),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
